effect.shader:
void main(){
    vec2 px=1.0/acScreenSize;
    float l =dot(texture2DCv(inputImg.texture, acScreenNorm-vec2(px.x,0.0)).rgb,vec3(0.333));
    float r =dot(texture2DCv(inputImg.texture, acScreenNorm+vec2(px.x,0.0)).rgb,vec3(0.333));
    float u =dot(texture2DCv(inputImg.texture, acScreenNorm-vec2(0.0,px.y)).rgb,vec3(0.333));
    float dn=dot(texture2DCv(inputImg.texture, acScreenNorm+vec2(0.0,px.y)).rgb,vec3(0.333));
    vec3 nrm=normalize(vec3((l-r)*height*8.0,(u-dn)*height*8.0,1.0));
    vec2 off=nrm.xy*refraction*0.05;
    vec4 col=texture2DCv(inputImg.texture, acScreenNorm+off);
    float fres=pow(1.0-nrm.z, 3.0)*rim;
    col.rgb += fres;
    gl_FragColor=vec4(clamp(col.rgb,0.0,1.0), col.a);
}
